static std::vector<double> parseNumbers(const std::string& text,int count){std::string s=text;for(char& c:s)if(c==','||c=='['||c==']')c=' ';std::istringstream in(s);std::vector<double> values;double n;while(in>>n){if(!std::isfinite(n))throw std::runtime_error("Coordinates must be finite");values.push_back(n);}if(values.size()!=size_t(count)||!in.eof())throw std::runtime_error("Expected "+std::to_string(count)+" comma-separated numbers");return values;}
static std::string displayNumber(double n){char value[64];std::snprintf(value,sizeof value,"%.6g",n);return value;}

