void App::requestRender(){
    if(!loaded||!renderer||panel==0)return;
    std::string context=state["content_digest"].str()+":"+std::to_string(panel)+":"+std::to_string(frame)+":";for(bool b:overlays)context+=b?'1':'0';context+=showModel?'1':'0';if(panel==1&&proposedShapes.isObject())context+=proposedShapes.dump();
    std::string geometryContext=context;if(panel==1&&textureContext!=geometryContext){emptyModelTexture=!hasVisiblePixels(canvas.composed.crop(currentRect()));textureContext=geometryContext;}context+=":transparent-checker";std::string key=context+":"+J(yaw).dump()+":"+J(pitch).dump()+":zoom:"+J(sceneZoom).dump();if(panel==1&&!state["scene_animation"].null())key+=":scene:"+J(sceneTime(state["scene_animation"],elapsed)).dump();if(scenePlayer)key+=":state:"+scenePlayer->state+":"+std::to_string(scenePlayer->generation)+":local:"+J(scenePlayer->at).dump();if(key==renderKey)return;renderKey=key;sceneContext=context;++sceneSerial;
    if(GetFocus()!=shapeYaw)setText(shapeYaw,displayNumber(yaw));if(GetFocus()!=shapePitch)setText(shapePitch,displayNumber(pitch));
    sceneHeading->redraw();
    if(gpu&&gpu->available){
        gpu->setBackground(0);if(gpuContext!=geometryContext){std::vector<std::string> visible;for(int i=0;i<3;++i)if(overlays[i])visible.push_back(std::array<std::string,3>{"base","collision","selection"}[i]);gpu->configure(proposedShapes.isObject()?proposedShapes:state["shapes"],canvas.composed.crop(currentRect()),visible,showModel,state["scene_animation"]);gpuContext=geometryContext;}
        gpu->time(elapsed);gpu->angles(yaw,pitch);gpu->magnification(sceneZoom);gpu->playback(scenePlayer?scenePlayer->view():J());sceneView->redraw();sceneHeading->redraw();
        // Continuous orbit updates a persistent GPU scene only. A software hit
        // map is refreshed on release, not once per incoming mouse event.
        if(panning||(panel==1&&!state["scene_animation"].null()))return;
    }
    auto found=renderCache.find(key);if(found!=renderCache.end()){rendered=std::make_shared<RenderReady>(*found->second);rendered->serial=sceneSerial;sceneView->redraw();return;}
    RenderJob job;job.key=key;job.background=0;job.context=context;job.serial=sceneSerial;job.definition=proposedShapes.isObject()?proposedShapes:state["shapes"];job.scene=panel==1?state["scene_animation"]:J();job.time=elapsed;job.sceneView=scenePlayer?scenePlayer->view():J();job.atlas=canvas.composed.crop(currentRect());job.size=400;job.yaw=yaw;job.pitch=pitch;job.zoom=sceneZoom;for(int i=0;i<3;++i)if(overlays[i])job.overlays.push_back(std::array<std::string,3>{"base","collision","selection"}[i]);job.showModel=showModel;renderer->submit(std::move(job));sceneView->redraw();
}
void App::renderComplete(RenderReady* value){auto result=std::shared_ptr<RenderReady>(value);++renderCount;lastRenderMs=result->ms;if(!renderCache.count(result->key))renderOrder.push_back(result->key);renderCache[result->key]=result;while(renderOrder.size()>16){renderCache.erase(renderOrder.front());renderOrder.pop_front();}
    // An orbit frame remains valid when a newer angle is already queued. Present
    // every newly completed frame for the same document/texture/overlay context.
    if(result->context==sceneContext&&(!rendered||rendered->context!=sceneContext||result->serial>=rendered->serial)){rendered=result;sceneView->redraw();}}
