    if(group==4){for(auto [name,title]:{std::pair<const char*,const wchar_t*>{"grid",L"像素网格\tCtrl+'"},{"tile",L"3 × 3 平铺\tT"},{"onion",L"洋葱皮\tAlt+O"},{"fit",L"适应窗口\tCtrl+0"}})add(title,[this,name]{buttons.at(GetDlgCtrlID(handles[name])).click();});add(L"原尺寸\tCtrl+1",[this]{setZoom(1);});add(L"颜色与图层面板",[this]{inspectorVisible=!inspectorVisible;layout();});add(L"帧时间轴",[this]{timelineVisible=!timelineVisible;layout();});add(L"重置面板布局",[this]{inspectorVisible=timelineVisible=true;rightWidth=294;timelineHeight=182;layout();fit();});add(L"C++ 命令入口",[this]{message=L"pixelforge ui --runtime <会话目录> help  ·  CLI/MCP 与桌面共用独立核心";statusBar->redraw();});}
